def fig(name,page,box,label):
 source=OUT/f'sgk-kntt/pages/{page:03}.jpg'; im=Image.open(source);w,h=im.size
 rect=[round(box[0]*w),round(box[1]*h),round(box[2]*w),round(box[3]*h)]
 file=f'sgk-kntt/verified-figures/{name}.png';target=OUT/file;target.parent.mkdir(exist_ok=True);im.crop(rect).save(target)
 crops.append({'id':f'sgk-original-{name}','book':'sgk-kntt','page':page,'label':label,'image':{'file':file,'page':page,'rect':rect,'width':rect[2]-rect[0],'height':rect[3]-rect[1]},'status':'isolated_visual_check','colorStatus':'original','sourceSha256':hashlib.sha256(source.read_bytes()).hexdigest()})
 return {'url':'/api/book-bank/asset?file='+file.replace('/','%2F'),'description':label,'origin':'source_crop'}
