def add(lesson,page,location,prompt,answer,bloom='understand',rationale='Giải thích hoặc diễn giải mối quan hệ vật lí từ kiến thức đã học.',figure=None,kind='written',options=None,key=None):
 n=len(rows)+1
 q={'id':f'sgk-kntt-nuclear-{n:03}','kind':kind,'topic':lesson,'chapter':'Vật lí hạt nhân','level':{'remember':'Nhận biết','understand':'Thông hiểu','apply':'Vận dụng','analyze':'Vận dụng','evaluate':'Vận dụng','create':'Vận dụng'}[bloom],'prompt':prompt,'explanation':answer,'points':1,'source':{'book':'Sách giáo khoa Vật lí 12 · Kết nối tri thức','bookId':'sgk-kntt','sequence':n,'label':f'Câu {n} · {location}','pages':[page],'printedPages':[page-2]},'bloom':{'level':bloom,'rationale':rationale,'review':'reviewed'},'status':'ready','notes':['Phần dẫn đối chiếu trực quan bản mẫu SGK tháng 1/2024; lời giải do người biên soạn xây dựng, không phải đáp án chính thức của nhà xuất bản.','Nhãn Bloom là phân loại nội bộ theo yêu cầu trả lời; chưa thẩm định độc lập.']}
 if figure:q['figure']=F[figure]
 if options:q.update(options=options,answer=key)
 rows.append(q)
# B21: opening, every independent question/subtask, ending on the last question (not recap boxes).
add('B21',93,'Khởi động tr. 91','Các nhà khoa học đã làm thế nào để phát hiện hạt nhân có kích thước nhỏ hơn nhiều so với nguyên tử, dù không thể quan sát bằng kính hiển vi quang học?','Dùng thí nghiệm tán xạ hạt alpha qua lá vàng; kết hợp đa số hạt đi gần thẳng và số ít lệch mạnh để suy ra vùng điện tích dương tập trung rất nhỏ.',figure='21.2')
add('B21',94,'Hoạt động 1a tr. 92','Dựa vào thí nghiệm tán xạ hạt alpha: tần suất đốm sáng lớn nhất tại vị trí (1), đối diện nguồn phát trong Hình 21.2b, chứng tỏ điều gì?','Đa số hạt alpha đi qua lá vàng gần như thẳng; phần lớn thể tích nguyên tử là khoảng trống.',figure='21.2')
add('B21',94,'Hoạt động 1b tr. 92','Tại sao có một số hạt alpha đổi hướng chuyển động khi đi qua lá vàng?','Hạt alpha mang điện dương chịu lực đẩy tĩnh điện khi đi gần hạt nhân vàng mang điện dương.',figure='21.2')
add('B21',94,'Hoạt động 1c tr. 92',r'Tần suất hạt alpha bật lại tới vị trí (2) chỉ bằng $10^{-4}$ lần tần suất hạt đi qua tới vị trí (1). Kết quả đó chứng tỏ điều gì?','Điện tích dương và phần lớn khối lượng nguyên tử tập trung trong hạt nhân rất nhỏ; chỉ rất ít hạt đi đủ gần hạt nhân để bị lệch góc lớn.',figure='21.2')
add('B21',94,'Hoạt động 2a tr. 92','Mô tả mô hình hành tinh nguyên tử của Rutherford trong Hình 21.5a.','Hạt nhân rất nhỏ, mang điện dương ở tâm; electron chuyển động xung quanh, phần lớn thể tích nguyên tử là khoảng trống.','remember','Nhắc lại các thành phần của mô hình đã giới thiệu.',figure='21.5')
add('B21',94,'Hoạt động 2b tr. 92','Giải thích mô hình cấu tạo nguyên tử của Rutherford dựa vào kết quả tán xạ ở các ý 1a, 1b, 1c.','Liên hệ hạt đi thẳng với khoảng trống; hạt lệch mạnh với lực đẩy của vùng điện tích dương tập trung; hạt bật ngược hiếm với kích thước hạt nhân rất nhỏ.','analyze','Phân tách ba bằng chứng và nối mỗi bằng chứng với một đặc điểm cấu trúc.',figure='21.2')
add('B21',95,'Câu hỏi tr. 93',r'Xác định khối lượng proton và neutron theo đơn vị amu. Dữ kiện cùng trang: $m_p=1{,}67262\times10^{-27}$ kg; $m_n=1{,}67493\times10^{-27}$ kg; $1\ \mathrm{amu}=1{,}66054\times10^{-27}$ kg.',r'$m_p\approx1{,}00728$ amu; $m_n\approx1{,}00866$ amu. Chia mỗi khối lượng theo kg cho khối lượng ứng với 1 amu.','apply','Thực hiện phép đổi đơn vị bằng số liệu đã cho.')
add('B21',96,'Câu hỏi tr. 94',r'Công thức $R=1{,}2\times10^{-15}A^{1/3}$ (m) cho kết quả tốt hơn với $A>12$. Nghiệm lại cho các hạt nhân trong Bảng 21.1. Số khối A và bán kính hạt nhân (fm): H (1; 0,9), He (4; 1,7), O (16; 2,7), Si (28; 3,1), Fe (56; 3,7), Cd (114; 4,6), Au (197; 5,4), U (238; 5,9).','Tính R dự đoán lần lượt khoảng 1,20; 1,90; 3,02; 3,64; 4,59; 5,82; 6,98; 7,44 fm, rồi so sánh với bảng. Bảng trong bản mẫu này không khớp tốt công thức ở nhiều hạt nhân A>12; không tự thay số liệu bảng để ép kết luận. Giáo viên cần đối chiếu bản SGK đang dùng.','evaluate','Tính kết quả rồi kiểm tra mức phù hợp của công thức với dữ liệu, nhận diện chênh lệch.')
add('B21',97,'Câu hỏi 1 tr. 95',r'Trong kí hiệu hạt nhân, đại lượng $N=A-Z$ cho biết số lượng loại hạt nào? Vì sao?',r'N là số neutron, vì A là tổng proton và neutron còn Z là số proton.')
add('B21',97,'Câu hỏi 2 tr. 95',r'Bằng cách nào có thể tìm số Z và số N của hạt nhân có kí hiệu dạng ${}^{A}\mathrm{X}$?','Tra số hiệu nguyên tử Z của nguyên tố X trong bảng tuần hoàn; lấy N=A−Z.')
add('B21',97,'Câu hỏi 3 tr. 95','Viết kí hiệu hạt nhân vàng (Au), helium (He), nitrogen (N), biết số nucleon lần lượt là 197; 4; 14.',r'${}^{197}_{79}\mathrm{Au}$; ${}^{4}_{2}\mathrm{He}$; ${}^{14}_{7}\mathrm{N}$. Dùng bảng tuần hoàn để xác định Z.','apply','Sử dụng số khối đã cho và bảng tuần hoàn để lập kí hiệu hạt nhân.')
add('B21',97,'Câu hỏi đồng vị tr. 95','Giải thích tại sao các chất cấu tạo từ cùng một loại nguyên tố nhưng khối lượng riêng vẫn có thể khác nhau.','Các đồng vị cùng Z nhưng khác N nên khối lượng nguyên tử khác nhau. Ngoài thành phần đồng vị, khối lượng riêng còn phụ thuộc cấu trúc và trạng thái vật chất; chỉ so sánh do đồng vị khi các điều kiện khác tương đương.')
# B22
add('B22',98,'Khởi động tr. 96','Người ta đã thực hiện thí nghiệm phát hiện phản ứng hạt nhân như thế nào? Các hạt nhân có thể biến đổi thành các hạt nhân khác không?',r'Bắn hạt alpha vào nitrogen; vết tương tác trong buồng sương cho bằng chứng tạo oxygen và proton. Phản ứng minh họa: ${}^{4}_{2}\mathrm{He}+{}^{14}_{7}\mathrm{N}\to{}^{17}_{8}\mathrm{O}+{}^{1}_{1}\mathrm{H}$.',figure='22.2')
add('B22',99,'Hoạt động tr. 97','So sánh tổng điện tích và tổng số nucleon của các hạt nhân trước và sau tương tác trong Hình 22.2.',r'Trước: Z=2+7=9, A=4+14=18. Sau: Z=8+1=9, A=17+1=18. Hai tổng được bảo toàn.','apply','Đọc kí hiệu trong hình và tính hai tổng ở mỗi vế.',figure='22.2')
add('B22',99,'Câu hỏi tr. 97','Trình bày sự khác nhau giữa phản ứng hạt nhân và phản ứng hóa học.','Phản ứng hạt nhân thay đổi cấu tạo hạt nhân và có thể biến đổi nguyên tố; phản ứng hóa học chủ yếu sắp xếp electron/liên kết, hạt nhân nguyên tử giữ nguyên.')
add('B22',99,'Hoạt động 1 tr. 97',r'Viết biểu thức liên hệ số khối và điện tích trong phản ứng ${}^{A_1}_{Z_1}\mathrm{X}_1+{}^{A_2}_{Z_2}\mathrm{X}_2\to{}^{A_3}_{Z_3}\mathrm{X}_3+{}^{A_4}_{Z_4}\mathrm{X}_4$.',r'$A_1+A_2=A_3+A_4$; $Z_1+Z_2=Z_3+Z_4$.','apply','Áp dụng hai định luật bảo toàn vào phản ứng được cho.')
add('B22',99,'Hoạt động 2 tr. 97',r'Khi ${}^{235}_{92}\mathrm{U}$ hấp thụ neutron, tạo hạt nhân X rồi phân rã thành ${}^{99}_{42}\mathrm{Mo}$, ba neutron và hạt nhân Y. a) Viết các phương trình. b) Dùng bảng tuần hoàn xác định X, Y.',r'${}^{235}_{92}\mathrm{U}+{}^{1}_{0}\mathrm{n}\to{}^{236}_{92}\mathrm{U}^{*}$; ${}^{236}_{92}\mathrm{U}^{*}\to{}^{99}_{42}\mathrm{Mo}+{}^{134}_{50}\mathrm{Sn}+3{}^{1}_{0}\mathrm{n}$. X là uranium-236 kích thích, Y là tin-134.','apply','Tính A, Z chưa biết theo bảo toàn, rồi tra tên nguyên tố.')
add('B22',100,'Câu hỏi tr. 98','Vì sao tách các nucleon ra khỏi hạt nhân cần một năng lượng lớn?','Phải cung cấp năng lượng để thắng liên kết do tương tác hạt nhân mạnh giữa các nucleon.')
add('B22',100,'Hoạt động 1 tr. 98','Nêu mối liên hệ giữa độ bền vững của hạt nhân và năng lượng liên kết riêng.','Năng lượng liên kết riêng lớn biểu thị nucleon được liên kết chặt hơn theo cách so sánh ở SGK. Độ bền đối với từng kênh phân rã còn phụ thuộc cấu trúc và điều kiện năng lượng, không chỉ một đại lượng E/A.')
add('B22',100,'Hoạt động 2a tr. 98','Từ Hình 22.3, chỉ ra hai hạt nhân bền vững nhất và ước lượng năng lượng liên kết riêng của chúng.',r'Trong các điểm được gắn nhãn trên hình, ${}^{56}\mathrm{Fe}$ và ${}^{89}\mathrm{Y}$ gần đỉnh; khoảng 8,8 MeV/nuclon. Đây là ước lượng từ đồ thị SGK, không phải khẳng định hai đồng vị bền nhất trong toàn bộ bảng nuclide.','understand','Diễn giải điểm cực đại của đồ thị trong phạm vi các điểm được biểu diễn.',figure='22.3')
add('B22',100,'Hoạt động 2b tr. 98',r'Từ Hình 22.3, xác định năm hạt nhân nhẹ ($A\le30$) và bốn hạt nhân nặng ($A\ge160$) có năng lượng liên kết riêng nhỏ hơn 8,2 MeV.',r'Nhẹ: ${}^{2}\mathrm{H}$, ${}^{4}\mathrm{He}$, ${}^{6}\mathrm{Li}$, ${}^{9}\mathrm{Be}$, ${}^{11}\mathrm{B}$. Nặng: ${}^{160}\mathrm{Dy}$, ${}^{197}\mathrm{Au}$, ${}^{209}\mathrm{Bi}$, ${}^{238}\mathrm{U}$. Đọc theo các điểm được gắn nhãn, có sai số ước lượng.','analyze','Lọc các điểm theo đồng thời miền số khối và ngưỡng năng lượng.',figure='22.3')
add('B22',101,'Câu hỏi tr. 99',r'Tính độ hụt khối hạt nhân ${}^{16}_{8}\mathrm{O}$, biết khối lượng hạt nhân là 15,99492 amu. Dùng $m_p=1{,}00728$ amu, $m_n=1{,}00866$ amu từ bài.',r'$\Delta m=8m_p+8m_n-m_O=0{,}13260$ amu. Giá trị khối lượng ở bản mẫu cần đối chiếu cách dùng khối lượng hạt nhân/nguyên tử; đáp số này theo đúng dữ kiện đã cho.','apply','Thay Z, N và khối lượng vào công thức độ hụt khối.')
add('B22',102,'Hoạt động a tr. 100',r'Tính năng lượng liên kết và năng lượng liên kết riêng của ${}^{4}_{2}\mathrm{He}$. Dữ kiện cùng bài: khối lượng hạt nhân 4,00015 amu, $m_p=1{,}00728$ amu, $m_n=1{,}00866$ amu; $1\ \mathrm{amu}\,c^2=931{,}5$ MeV.',r'$\Delta m=0{,}03173$ amu; $E_{lk}\approx29{,}557$ MeV; $E_{lk}/A\approx7{,}389$ MeV/nuclon, theo số liệu đã cho.','apply','Dùng độ hụt khối, rồi đổi sang năng lượng và chia cho số nucleon.')
add('B22',102,'Hoạt động b tr. 100',r'Tìm hệ số chuyển đổi giữa amu và $\mathrm{MeV}/c^2$. Dùng $1\ \mathrm{amu}=1{,}66054\times10^{-27}$ kg, $c\approx3{,}00\times10^8$ m/s và $1\ \mathrm{MeV}=1{,}60218\times10^{-13}$ J.',r'$1\ \mathrm{amu}\approx932{,}8\ \mathrm{MeV}/c^2$ với c làm tròn như đề. Dùng c chính xác hơn cho hệ số chuẩn khoảng 931,5. Ghi rõ mức làm tròn sử dụng.','apply','Đổi khối lượng sang năng lượng bằng E=mc² rồi đổi J sang MeV.')
add('B22',103,'Hoạt động tr. 101','Phân hạch hạt nhân là gì? Nêu đặc điểm phản ứng phân hạch uranium.','Một hạt nhân nặng bị tách thành các mảnh nhẹ hơn; uranium-235 hấp thụ neutron tạo uranium-236 kích thích rồi phân hạch, giải phóng neutron và năng lượng. Các nhánh sản phẩm có thể khác nhau.',figure='22.6')
add('B22',103,'Câu hỏi 1 tr. 101','Nêu đặc điểm phản ứng phân hạch dây chuyền.','Neutron từ một lần phân hạch kích thích các lần phân hạch tiếp theo. Phản ứng duy trì khi trung bình đủ neutron gây phân hạch mới; có thể tắt, ổn định hoặc tăng tùy điều kiện.',figure='22.7')
add('B22',103,'Câu hỏi 2 tr. 101',r'Tính năng lượng tỏa khi phân hạch hoàn toàn 1 kg ${}^{235}_{92}\mathrm{U}$; mỗi phân hạch tỏa 200 MeV. Dùng $N_A=6{,}022\times10^{23}\ \mathrm{mol}^{-1}$, $1\ \mathrm{MeV}=1{,}602\times10^{-13}$ J.',r'$Q=(1000/235)N_A\times200\times1{,}602\times10^{-13}\approx8{,}21\times10^{13}$ J.','apply','Tính số hạt từ khối lượng và nhân năng lượng mỗi phân hạch.')
add('B22',105,'Câu hỏi 1 tr. 103','Tổng hợp hạt nhân là gì? Nêu điều kiện xảy ra phản ứng tổng hợp hạt nhân.','Các hạt nhân nhẹ kết hợp thành hạt nhân nặng hơn. Cần đủ năng lượng để vượt rào đẩy Coulomb; trong nhiệt hạch cần nhiệt độ, mật độ và thời gian duy trì phù hợp.','remember','Nhắc lại định nghĩa và các điều kiện đã giới thiệu.')
add('B22',105,'Câu hỏi 2 tr. 103','So sánh định tính tổng hợp hạt nhân và phân hạch về nhiên liệu và điều kiện xảy ra phản ứng.','Tổng hợp dùng các hạt nhân nhẹ, cần điều kiện đưa chúng đến đủ gần nhau; phân hạch dùng hạt nhân nặng, có thể được kích thích bằng neutron thích hợp. So sánh theo cùng hai tiêu chí.')
# B23
add('B23',106,'Khởi động tr. 104','Trong thí nghiệm Becquerel, tấm phim có vết sáng dù mẫu uranium được để trong bóng tối. Nguyên nhân nào gây tác dụng lên phim?','Bức xạ phát ra tự phát từ chất chứa uranium tác động lên phim; hiện tượng không đòi hỏi mẫu được chiếu sáng trước.')
add('B23',106,'Hoạt động 1 tr. 104','Hiện tượng phóng xạ có tính tự phát hay phụ thuộc nhiệt độ, áp suất của môi trường?','Theo mô hình SGK, phân rã phóng xạ có tính tự phát, không bị điều khiển bởi thay đổi nhiệt độ, áp suất thông thường.')
add('B23',106,'Hoạt động 2 tr. 104','Có thể điều khiển hiện tượng phóng xạ không? Tại sao?','Không điều khiển thời điểm phân rã từng hạt nhân bằng điều kiện môi trường thông thường; có thể kiểm soát phơi nhiễm bằng che chắn, khoảng cách và thời gian.')
add('B23',107,'Hoạt động tr. 105','Bảng 23.1: các khoảng 0–5; 5–10; 10–15; 15–20; 20–25; 25–30 s có số tia ghi nhận lần lượt 1; 3; 2; 0; 3; 1. a) Nhận xét số lượng phân rã trong những khoảng bằng nhau. b) Có dự đoán chính xác thời điểm và số lượng phân rã từng khoảng được không?','Số đếm dao động, không bằng nhau dù khoảng thời gian bằng nhau. Không dự đoán chính xác thời điểm phân rã từng hạt hay từng số đếm; chỉ dự đoán thống kê khi xét nhiều hạt/lượt. Số đếm còn phụ thuộc hiệu suất ghi nhận.','analyze','So sánh các khoảng đo và phân biệt kết quả ngẫu nhiên với dự đoán thống kê.')
add('B23',108,'Câu hỏi alpha 1 tr. 106',r'Nêu các tính chất tia phóng xạ $\alpha$.',r'Là hạt nhân ${}^{4}_{2}\mathrm{He}$, điện tích +2e, ion hóa mạnh và đâm xuyên kém; bị lệch trong điện/từ trường.','remember','Nhắc lại bản chất và tính chất của loại bức xạ.',figure='23.4')
add('B23',108,'Câu hỏi alpha 2 tr. 106',r'Viết phương trình phân rã $\alpha$ của ${}^{235}_{92}\mathrm{U}$.',r'${}^{235}_{92}\mathrm{U}\to{}^{231}_{90}\mathrm{Th}+{}^{4}_{2}\mathrm{He}$.','apply','Áp dụng bảo toàn A và điện tích cho phân rã alpha.')
add('B23',108,'Câu hỏi beta 1 tr. 106',r'Nêu các tính chất phóng xạ $\beta$.',r'$\beta^-$ là electron, $\beta^+$ là positron, vận tốc lớn; mức ion hóa và đâm xuyên khác alpha; chịu lực trong điện/từ trường.','remember','Nhắc lại bản chất hai loại tia beta.')
add('B23',108,'Câu hỏi beta 2 tr. 106',r'Viết phương trình phân rã $\beta^-$ của ${}^{90}_{38}\mathrm{Sr}$ và $\beta^+$ của ${}^{18}_{9}\mathrm{F}$.',r'${}^{90}_{38}\mathrm{Sr}\to{}^{90}_{39}\mathrm{Y}+{}^{0}_{-1}\mathrm{e}+\bar\nu$; ${}^{18}_{9}\mathrm{F}\to{}^{18}_{8}\mathrm{O}+{}^{0}_{1}\mathrm{e}+\nu$.','apply','Áp dụng quy tắc giữ A, thay Z đúng chiều và bảo toàn điện tích.')
add('B23',109,'Câu hỏi gamma 1 tr. 107',r'Nêu các tính chất phóng xạ $\gamma$.','Là photon năng lượng cao, không mang điện, không lệch trong điện/từ trường, đâm xuyên mạnh; phát khi hạt nhân chuyển về mức năng lượng thấp hơn.','remember','Nhắc lại bản chất và tính chất gamma.')
add('B23',109,'Câu hỏi gamma 2 tr. 107',r'Technetium ${}^{99}_{43}\mathrm{Tc}^{*}$ là đồng vị phát gamma dùng trong chụp ảnh y học hạt nhân. Viết phương trình phân rã này.',r'${}^{99}_{43}\mathrm{Tc}^{*}\to{}^{99}_{43}\mathrm{Tc}+\gamma$. Số A và Z không đổi.','apply','Áp dụng đặc điểm chuyển mức năng lượng không thay đổi A, Z.')
add('B23',109,'Hoạt động 1 tr. 107','Giải thích hướng lệch của các tia phóng xạ trong điện trường và từ trường ở Hình 23.3.',r'$\alpha,\beta^+$ mang điện dương và $\beta^-$ mang điện âm nên lực điện có chiều ngược nhau; gamma trung hòa nên không lệch. Trong từ trường dùng lực Lorentz theo hướng vận tốc, từ trường và dấu điện tích.','understand','Giải thích đường đi từ điện tích và lực tương ứng.',figure='23.3')
add('B23',109,'Hoạt động 2 tr. 107','Giải thích vì sao tia alpha, beta và gamma có khả năng đâm xuyên khác nhau.','Bản chất, khối lượng, điện tích và cơ chế tương tác với vật chất khác nhau. Alpha mất năng lượng nhanh do ion hóa mạnh; beta thường xuyên sâu hơn; photon gamma tương tác theo cơ chế khác và xuyên sâu hơn trong mô tả định tính SGK.',figure='23.4')
add('B23',110,'Câu hỏi 1 tr. 108','Phát biểu định nghĩa chu kì bán rã.','Khoảng thời gian để số hạt nhân chưa phân rã của mẫu giảm còn một nửa giá trị ban đầu theo mô hình thống kê.','remember','Nhắc lại định nghĩa chu kì bán rã.')
add('B23',110,'Câu hỏi 2 tr. 108',r'Đồng vị ${}^{15}_{8}\mathrm{O}$ sau 244 s có 75% số hạt nhân ban đầu đã phân rã. Tính chu kì bán rã.',r'Còn 25% nên $244=2T$, do đó $T=122$ s.','apply','Chuyển phần đã phân rã sang phần còn lại và áp dụng định luật bán rã.')
add('B23',111,'Câu hỏi 1 tr. 109','Nêu ý nghĩa của hằng số phóng xạ.',r'$\lambda=\ln2/T$ đặc trưng tốc độ phân rã của đồng vị; với nhiều hạt, độ phóng xạ trung bình $H=\lambda N$.')
add('B23',111,'Câu hỏi 2a tr. 109',r'Dược chất Flortaucipir chứa ${}^{18}_{9}\mathrm{F}$ có chu kì bán rã khoảng 110 phút. Sau bao lâu lượng đồng vị giảm còn 10% và 1% lúc đầu?',r'$t=T\log_2(N_0/N)$; khoảng 365,4 phút (10%) và 730,8 phút (1%).','apply','Giải phương trình suy giảm mũ cho hai tỉ lệ đã cho.')
add('B23',111,'Câu hỏi 2b tr. 109',r'Mỗi mL Flortaucipir có độ phóng xạ ban đầu $10^9$ Bq, đồng vị ${}^{18}_{9}\mathrm{F}$ có T=110 phút. Tính số hạt đồng vị trong mỗi mL lúc đầu và sau một ngày.',r'$N_0=H_0T/\ln2\approx9{,}52\times10^{12}$ hạt, với T=6600 s. Sau 1440 phút: $N\approx1{,}09\times10^9$ hạt.','apply','Đổi thời gian thống nhất, dùng H=λN rồi suy giảm theo thời gian.')
add('B23',113,'Hoạt động 1 tr. 111','Tìm hiểu tác hại của phóng xạ đến sức khỏe: a) các loại phơi nhiễm; b) biểu hiện; c) cách phòng tránh.','Phân biệt chiếu xạ ngoài với chất phóng xạ vào cơ thể; tác động phụ thuộc loại bức xạ, mức và thời gian phơi nhiễm. Phòng tránh theo kiểm soát nguồn, thời gian, khoảng cách, che chắn và hướng dẫn chuyên môn. Khi trình bày biểu hiện phải dùng nguồn y tế có tác giả/cơ quan; không suy chẩn đoán cho cá nhân.','analyze','Phân loại con đường phơi nhiễm và liên hệ với biện pháp bảo vệ; cần bằng chứng nguồn.')
add('B23',113,'Hoạt động 2 tr. 111','Nêu tên các địa điểm/vật có nguy cơ phóng xạ ở Hình 23.9. Nếu gặp các biển cảnh báo đó, em sẽ làm gì?','Nhà máy/khu vực hạt nhân, thiết bị chứa nguồn, phòng đặt máy gia tốc, phòng PET/CT. Không tự tiếp cận hoặc mở vật chứa; làm theo biển và hướng dẫn của người phụ trách.','apply','Áp dụng ý nghĩa biển cảnh báo vào tình huống cụ thể.',figure='23.9')
add('B23',114,'Hoạt động 1 tr. 112','Tìm hiểu và nêu thêm nguyên tắc an toàn phóng xạ. Việc tuân thủ quy tắc có vai trò gì?','Kiểm soát nguồn và tiếp cận, dùng thiết bị bảo vệ/giám sát phù hợp, đào tạo và làm theo quy trình đơn vị. Vai trò: giảm phơi nhiễm không cần thiết và nguy cơ nhiễm bẩn; không tự thực hành với nguồn thật.')
add('B23',114,'Hoạt động 2 tr. 112','Nguồn và chất thải phóng xạ được bảo quản trong thiết bị lưu trữ (Hình 23.12) hoặc hầm cách li nguồn nước (Hình 24.2). Người ta áp dụng nguyên tắc an toàn nào?','Che chắn bằng vật liệu thích hợp, lưu giữ/kiểm soát nguồn, cách li tránh chất phóng xạ phát tán vào môi trường và nguồn nước. Nêu cả che chắn bức xạ và ngăn nhiễm bẩn.',figure='23.12')
# B24
add('B24',116,'Khởi động tr. 114','Nhà máy điện hạt nhân có những ưu điểm và nhược điểm gì?','Nêu khả năng phát điện ổn định, nhiên liệu có mật độ năng lượng cao và phát thải trực tiếp thấp; cân nhắc chi phí đầu tư, chất thải, an toàn, thời gian xây dựng và tháo dỡ. Kết luận cần tiêu chí so sánh, không chỉ liệt kê.','evaluate','Cân nhắc lợi ích và hạn chế theo các tiêu chí năng lượng, môi trường và kinh tế.')
add('B24',118,'Câu hỏi 1 tr. 116','Vì sao nhà máy điện hạt nhân thường được xây cạnh hồ, sông hoặc bờ biển?','Cần nguồn nước để làm mát/ngưng tụ và thải nhiệt; vị trí còn phải đáp ứng điều kiện an toàn, địa chất, môi trường.')
add('B24',118,'Câu hỏi 2 tr. 116','Liệt kê các nguy cơ ảnh hưởng sức khỏe con người và môi trường nếu xảy ra sự cố tại lò phản ứng hạt nhân.','Có thể phát tán chất phóng xạ, gây chiếu xạ/nhiễm bẩn, ảnh hưởng nước, đất và hệ sinh thái. Mức nguy cơ tùy kịch bản sự cố và biện pháp kiểm soát; không khẳng định mọi sự cố có hậu quả như nhau.')
add('B24',118,'Thảo luận 1 tr. 116','Nêu vai trò nhà máy điện hạt nhân trong đời sống.','Cung cấp điện năng, góp phần bảo đảm nguồn điện ổn định; liên hệ điều kiện của hệ thống điện và quản lí an toàn.')
add('B24',118,'Thảo luận 2 tr. 116','Đánh giá ưu điểm, nhược điểm và cơ hội phát triển của nhà máy điện hạt nhân.','So sánh theo phát điện ổn định, phát thải vòng đời, chi phí, thời gian xây dựng, chất thải và an toàn; dẫn nguồn cho nhận định cơ hội, tránh chỉ khẳng định ưu/nhược điểm.','evaluate','Đưa ra nhận định có tiêu chí và bằng chứng, cân nhắc các phương án.')
add('B24',119,'Thảo luận 1 tr. 117','Tại sao sử dụng tia gamma trong chụp ảnh phóng xạ cắt lớp bên trong cơ thể?','Photon phát ra từ đồng vị trong cơ thể có thể tới máy dò bên ngoài; hệ ghi nhận và xử lí tái tạo phân bố chất đánh dấu. Phân biệt SPECT với PET: PET ghi cặp photon do hủy positron–electron, không phải tia X từ máy CT.')
add('B24',119,'Thảo luận 2 tr. 117','Nêu vai trò y học hạt nhân trong đời sống.','Chẩn đoán qua theo dõi chất đánh dấu và điều trị bằng bức xạ phù hợp; thực hiện bởi cơ sở và nhân viên chuyên môn, có quy trình an toàn.')
add('B24',119,'Thảo luận 3 tr. 117','Đánh giá ưu điểm, nhược điểm và cơ hội phát triển y học hạt nhân.','Cân nhắc thông tin chức năng, khả năng chẩn đoán/điều trị với phơi nhiễm, chi phí, thiết bị, nhân lực và cung ứng đồng vị; dùng nguồn y tế có cơ quan/tác giả.','evaluate','Đánh giá công nghệ bằng tiêu chí lợi ích, hạn chế và điều kiện triển khai.')
add('B24',119,'Câu hỏi xạ trị tr. 117','Khi dùng máy xạ trị, tia phóng xạ có tác động lên tế bào khỏe mạnh không? Tìm thông tin về triệu chứng có thể xuất hiện sau xạ trị.','Có thể ảnh hưởng mô khỏe; vị trí và mức tác động tùy kế hoạch điều trị. Khi tìm triệu chứng cần ghi nguồn y tế và điều kiện, không suy chẩn đoán hoặc tự hướng dẫn điều trị từ bài học.')
add('B24',120,'Thảo luận 1 tr. 118','Nêu vai trò ứng dụng phóng xạ hạt nhân trong công nghệ sinh học và bảo quản thực phẩm.','Gây đột biến có chọn lọc trong nghiên cứu/chọn giống, theo dõi chất đánh dấu; chiếu xạ giảm vi sinh vật hoặc ức chế mọc mầm để bảo quản trong điều kiện phù hợp.')
add('B24',120,'Thảo luận 2 tr. 118','Đánh giá ưu điểm, nhược điểm và cơ hội phát triển các ứng dụng phóng xạ trong công nghệ sinh học và bảo quản thực phẩm.','Đánh giá theo hiệu quả, chất lượng sản phẩm, chi phí thiết bị, kiểm soát quy trình và nhu cầu thực tiễn. Dẫn nguồn cho điều kiện chiếu xạ; không đồng nhất thực phẩm chiếu xạ với thực phẩm nhiễm chất phóng xạ.','evaluate','Cân nhắc các tiêu chí và dùng bằng chứng cho kết luận.')
# B25: opening + three worked examples + six application exercises.
add('B25',121,'Khởi động tr. 119','Cần vận dụng những kiến thức cơ bản nào để giải bài tập về vật lí hạt nhân?','Cấu trúc/kí hiệu hạt nhân, bảo toàn trong phản ứng, năng lượng liên kết, định luật phóng xạ và ứng dụng; chọn công thức phù hợp dữ kiện.','remember','Nhắc lại các nhóm kiến thức chính của chủ đề.')
add('B25',121,'Bài tập ví dụ 1 tr. 119','Vì sao khi đưa mẫu phóng xạ (1) lại gần đầu thu điện (2) của tĩnh điện kế đã tích điện (Hình 25.1), độ lệch kim (3) giảm rất nhanh?','Bức xạ ion hóa không khí, làm không khí dẫn điện hơn; điện tích của tĩnh điện kế thất thoát nên kim nhanh về 0. Khác với chỉ đưa điện tích trái dấu đến gây tích điện ngược.',figure='25.1')
add('B25',122,'Bài tập ví dụ 2 tr. 120',r'Viết phương trình phân hạch ${}^{235}_{92}\mathrm{U}$ khi hấp thụ một neutron; sản phẩm gồm ${}^{140}_{58}\mathrm{Ce}$, ${}^{94}_{40}\mathrm{Zr}$, neutron và các tia $\beta^-$.',r'Theo bài toán bảo toàn của SGK: ${}^{235}_{92}\mathrm{U}+{}^{1}_{0}\mathrm{n}\to{}^{140}_{58}\mathrm{Ce}+{}^{94}_{40}\mathrm{Zr}+2{}^{1}_{0}\mathrm{n}+6{}^{0}_{-1}\mathrm{e}$. Đây là biểu diễn gộp; beta thường được phát trong các phân rã sau phân hạch, không khẳng định sáu electron đồng thời sinh ra ở bước phân hạch tức thời.','apply','Dùng đồng thời bảo toàn A và điện tích để tìm hệ số.')
add('B25',122,'Bài tập ví dụ 3 tr. 120',r'Máy xạ trị dùng ${}^{60}_{27}\mathrm{Co}$, T=5,3 năm. Theo điều kiện bài toán, cần bảo dưỡng trước khi độ phóng xạ giảm 7% và thay nguồn khi giảm 50%. Thiết lập lịch bảo dưỡng và thay nguồn.','Ngưỡng 7% ứng với t=5,3×ln(1/0,93)/ln2≈0,555 năm≈6,66 tháng; chọn chu kì 6 tháng để trước ngưỡng. Ngưỡng 50% ứng với 5,3 năm. Đây là điều kiện bài toán SGK, không phải quy định bảo dưỡng máy xạ trị thực tế.','apply','Dùng suy giảm mũ và chọn mốc thời gian đáp ứng điều kiện cho trước.',figure='25.2')
add('B25',123,'Bài tập vận dụng 1 tr. 121',r'Lực nào làm thay đổi phương của hạt alpha (${}^{4}_{2}\mathrm{He}$) khi bắn vào lá vàng mỏng?',r'C. Lực đẩy tĩnh điện giữa hai hạt nhân mang điện dương.','understand','Nhận diện cơ chế gây lệch từ bản chất điện tích của hai hạt.','21.2','choice',[r'Lực hạt nhân giúp hạt nhân ${}^{197}_{79}\mathrm{Au}$ đẩy ${}^{4}_{2}\mathrm{He}$.',r'Lực hạt nhân giúp hạt nhân ${}^{197}_{79}\mathrm{Au}$ hút ${}^{4}_{2}\mathrm{He}$.',r'Lực đẩy tĩnh điện giữa hạt nhân ${}^{197}_{79}\mathrm{Au}$ và ${}^{4}_{2}\mathrm{He}$.',r'Lực hút tĩnh điện giữa electron của nguyên tử vàng và ${}^{4}_{2}\mathrm{He}$.'],2)
add('B25',123,'Bài tập vận dụng 2 tr. 121','Bảng 25.1: t (s)=0; 30; 60; 120; 180; 240; 300; 360. H (Bq)=151; 85; 55; 31; 22; 15; 11; 9. a) Vẽ đồ thị H theo t. b) Ước lượng chu kì bán rã.','Vẽ đúng tám điểm, ghi trục/đơn vị và xu hướng. H₀/2=75,5 Bq nằm giữa t=30 và 60 s; nội suy đoạn đầu cho khoảng 39,5 s. Bảng không khớp một đường mũ đơn nhất qua mọi điểm (có thể có nền hoặc sai số); nêu cách ước lượng và giới hạn thay vì ép T=30 s.','analyze','Biểu diễn số liệu, xác định mức nửa ban đầu và nhận diện độ không khớp mô hình.')
add('B25',123,'Bài tập vận dụng 3 tr. 121',r'Mẫu gỗ cổ ghi nhận 240 phân rã mỗi phút, chứa 25 g carbon gồm ${}^{14}_{6}\mathrm{C}$ và ${}^{12}_{6}\mathrm{C}$. T của C-14 là 5730 năm; tỉ lệ C-12:C-14 ở sinh vật sống là $10^{12}:1$. a) Tính số nguyên tử C-14 hiện có. b) Tính tuổi mẫu. Dùng $N_A=6{,}022\times10^{23}\ \mathrm{mol}^{-1}$, một năm 365 ngày.','Giả sử hiệu suất đếm 100%, không có nền và mẫu kín: H=4 Bq; N=H×T/ln2≈1,043×10¹² hạt. N₀≈(25/12)N_A/10¹²≈1,255×10¹² hạt. Tuổi≈1529 năm. Nêu các giả thiết khi chuyển số đếm thành H.','apply','Chuyển tốc độ đếm, tính N và giải suy giảm từ tỉ lệ đồng vị ban đầu.')
add('B25',123,'Bài tập vận dụng 4 tr. 121',r'Nhà máy điện dùng ${}^{235}\mathrm{U}$; mỗi phân hạch tỏa 200 MeV, hiệu suất 36%, công suất điện 1400 MW. a) Tính khối lượng U-235 tiêu thụ một năm. b) Tính lượng than cần để tạo điện năng tương đương; năng suất tỏa nhiệt than 30 MJ/kg. Dùng năm 365 ngày, $N_A=6{,}022\times10^{23}\ \mathrm{mol}^{-1}$, $1\ \mathrm{MeV}=1{,}602\times10^{-13}$ J.','Q=Pđiện×t/0,36≈1,2264×10¹⁷ J; U-235≈1,494×10³ kg. Với than, đề không cho hiệu suất nhà máy than: mthan=Pđiện×t/(ηthan×30×10⁶). Nếu giả sử ηthan=0,36 thì≈4,088×10⁹ kg; không mặc nhiên lấy cùng hiệu suất nếu chưa nêu giả thiết.','analyze','Lập chuỗi chuyển hóa và kiểm tra dữ kiện còn thiếu để so sánh hai loại nhiên liệu.')
add('B25',124,'Bài tập vận dụng 5 tr. 122',r'Tháng 6/2024, người lái xe cần chờ bao lâu để chiếu xạ cùng lượng thuốc đông y tại Trung tâm chiếu xạ Hà Nội (Hình 25.3), nếu tháng 1/2022 mất 150 phút? Trung tâm vẫn dùng nguồn ${}^{60}_{27}\mathrm{Co}$ có T=5,3 năm.','Giả sử cùng liều cần thiết, hình học và hiệu suất, tốc độ chiếu tỉ lệ H nên thời gian xử lí tỉ lệ 1/H. Lấy khoảng cách tháng 1/2022→6/2024 là 29 tháng: thời gian≈150×2^(29/(12×5,3))≈205,8 phút. Không có ngày cụ thể nên đây là ước lượng theo tháng.','apply','Áp dụng suy giảm nguồn để giữ cùng lượng năng lượng hấp thụ theo giả thiết.',figure='25.3')
add('B25',124,'Bài tập vận dụng 6 tr. 122',r'FDG chứa ${}^{18}_{9}\mathrm{F}$ có T=110 phút, sản xuất bằng bắn phá ${}^{18}_{8}\mathrm{O}$ trong máy gia tốc (Hình 25.4). a) Xác định hạt tới khi sản phẩm còn có neutron và gamma. b) Hai bệnh nhân cùng cân nặng, dùng cùng đợt FDG ở thời điểm cách nhau 60 phút để đạt cùng độ phóng xạ mỗi kg. Người nào cần lượng FDG nhiều hơn và nhiều hơn bao nhiêu phần trăm?',r'a) Hạt tới là proton: ${}^{18}_{8}\mathrm{O}+{}^{1}_{1}\mathrm{p}\to{}^{18}_{9}\mathrm{F}+{}^{1}_{0}\mathrm{n}+\gamma$. b) Người tiêm sau cần lượng nhiều hơn, tỉ số $2^{60/110}\approx1{,}4595$, tăng khoảng 45,95%. Chỉ là bài toán tỉ lệ SGK, không dùng để quyết định liều người thật.','apply','Dùng bảo toàn A, Z và suy giảm hoạt tính để lập hai kết quả.',figure='25.4')
